<?php foreach($calendarTeams as $department=>$departmentLabel): $values=$calendarDayCounts[$department]??[]; ?>
<div class="intake-live-calendar-department" data-calendar-department="<?= $department ?>"><strong><?= view_h($departmentLabel) ?></strong><div class="intake-live-calendar-counts"><?php foreach($calendarStatuses as $state=>[$shortLabel,$fullLabel]): $count=max(0,(int)($values[$state]??0));$description=$fullLabel.' '.($calendarValuesLoaded?number_format($count).'건':'조회 중'); ?><span class="<?= $state ?><?= $calendarValuesLoaded&&$count===0?' intake-live-calendar-zero':'' ?>" aria-label="<?= view_h($departmentLabel.' '.$description) ?>" title="<?= view_h($description) ?>"><small><?= $shortLabel ?></small><b data-calendar-status="<?= $state ?>"><?= $calendarValuesLoaded?number_format($count):'—' ?></b></span><?php endforeach ?></div></div>
<?php endforeach ?>
